import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import CourseActivityLinks from '../../src/components/CourseActivityLinks';
import CourseActivityView from '../../src/pages/CourseActivityView';
import {emptyCourse} from '../../src/lib/course';
import {createAdvancedAssessmentStore} from '../../src/lib/advancedAssessmentStore';
import {createScientificWorkspaceStore} from '../../src/lib/scientificWorkspaceStore';
import {createBranchingEngineStore} from '../../src/lib/branchingEngineStore';
import {importAdvancedAssessmentPack} from '../../src/lib/advancedAssessment';
import {importScientificPack} from '../../src/lib/scientificWorkspace';
import {importBranchingPack} from '../../src/lib/branchingEngine';
import {syntheticAdvancedAssessmentPack} from './advanced-assessment-data';
import {syntheticScientificPack} from './scientific-data';
import {syntheticBranchingPack} from './branching-data';
import {SAMPLE_ASSIGNMENT} from '../../src/lib/spreadsheetAssignments';
import {requestNavigation} from '../../src/lib/navigationGuard';
import {viewToPath,pathToView} from '../../src/lib/routes';
import '../../src/styles.css';
import '../../src/advanced-assessment.css';
import '../../src/scientific.css';
import '../../src/branching.css';
const course=emptyCourse('Synthetic activity integration');course.id='synthetic-course';course.revision=9;
course.lessons=[{id:'intro',title:'Synthetic lesson',module:course.modules[0].id,body:'Existing lesson prose remains unchanged.'}];
course.advancedAssessments=[{...syntheticAdvancedAssessmentPack(),revision:7,lessonId:'intro'}];
course.scientificWorkspaces=[{...syntheticScientificPack(),revision:7,lessonId:'intro'}];
course.branchingScenarios=[{...syntheticBranchingPack(),revision:7,lessonId:'intro'}];
course.spreadsheetAssignments=[{...structuredClone(SAMPLE_ASSIGNMENT),title:'Synthetic spreadsheet',lessonId:'intro'}];
let writes=0;const states:Array<string|null>=[];
const stores=[createAdvancedAssessmentStore,createScientificWorkspaceStore,createBranchingEngineStore].map((create,i)=>(create as any)({read:async()=>states[i]??null,update:async(change:any)=>{writes++;return states[i]=await change(states[i]??null);},authorizeAdult:async()=>({actorId:'teacher',actorName:'Synthetic teacher',authorityKey:'test'}),learnerContext:async()=>({studentId:'alice',authorityKey:'alice'}),now:()=>new Date().toISOString()}));
const sources=[course.advancedAssessments[0],course.scientificWorkspaces[0],course.branchingScenarios[0]];
await Promise.all(stores.map(async(store,i)=>{const {lessonId:_,...source}=sources[i];const imported=[importAdvancedAssessmentPack,importScientificPack,importBranchingPack][i](source as any,`local-${i}`);let pack=await store.supervisor.savePack({...imported,courseOrigin:{courseId:course.id,courseRevision:9,sourceId:source.id,sourceRevision:7}},null);pack=await store.supervisor.approvePack(pack.id,pack.revision);await store.supervisor.assign({id:`assignment-${i}`,studentId:'alice',title:['Assigned reasoning','Assigned investigation','Assigned scenario'][i],instructions:'Synthetic instructions only.',pack,...(i===0?{variantId:'a'}:i===2?{startTick:0}:{})},null);}));
const initialWrites=writes;
function Fixture(){const [view,setView]=useState<any>({name:'lesson',courseId:course.id,lessonId:'intro'}),[mismatch,setMismatch]=useState(false);
 const selected=mismatch?{...course,advancedAssessments:course.advancedAssessments!.map(s=>({...s,instructions:s.instructions+' Changed content.'}))}:course;
 const go=(next:any)=>{if(requestNavigation('app',next)){setView(next);history.replaceState(null,'',viewToPath(next,[course],()=>undefined));}};
 const api:any={go,student:{id:'alice'},family:{parent:{password:null},students:[{id:'alice',name:'Alice'}]},progress:{attempts:[],lessonsDone:{}},advancedAssessmentLearner:stores[0].learner,scientificLearner:stores[1].learner,branchingLearner:stores[2].learner};
 Object.assign(window,{courseActivitiesFixture:{writes:()=>writes,initialWrites,route:()=>view,openMissing:()=>go({name:'courseActivity',courseId:course.id,kind:'advanced',sourceId:'missing'}),mismatch:()=>{if(requestNavigation('app',{name:'lesson'})){setMismatch(true);setView({name:'lesson'});}},roundtrip:()=>pathToView(location.pathname,'',[course],[])}});
 return <>{view.name==='courseActivity'?<CourseActivityView api={api} course={selected} kind={view.kind} sourceId={view.sourceId}/>:view.name==='parent'?<><h1>Synthetic adult unlock handoff</h1><button onClick={()=>go({name:'lesson',courseId:course.id,lessonId:'intro'})}>Back to synthetic lesson</button></>:<><h1>{view.name==='lesson'?'Synthetic lesson':'Synthetic course activities'}</h1><p>Existing lesson prose remains unchanged.</p><CourseActivityLinks api={api} course={selected} lessonId={view.name==='lesson'?'intro':undefined}/></>}</>;
}
createRoot(document.getElementById('root')!).render(<React.StrictMode><Fixture/></React.StrictMode>);
